@startuml

class User {
  + UserID : int
  + Name : string
  + Email : string
  + Birthdate : date
}

abstract class Account {}

class PersonalAccount {
  + MonthlyFee : double
}

class BusinessAccount {
  + CompanyName : string
}

class Page {
  + PageName : string
  + Visits : int
}

class AdvertisementPage {
  + BounceRate : double
  + ClickThroughRate : double
  + ConversionRate : double
}

User "1" -- "*" Account
PersonalAccount --|> Account
BusinessAccount --|> Account
Account "1" -- "*" Page
Page "0..1" -- "* AdvertisementPage"

@enduml

